const T = THREE;
const $ = s => document.querySelector(s);
const clamp=(v,a,b)=>v<a?a:v>b?b:v;
const lerp=(a,b,t)=>a+(b-a)*t;
const sm=t=>t<=0?0:t>=1?1:t*t*(3-2*t);
const r1=v=>Math.round(v*10)/10;

/* ---------- deterministic randomness (same camp for everyone) ---------- */
function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
const rng=mulberry32(1998);
function hash2(ix,iz){let h=Math.imul(ix|0,374761393)^Math.imul(iz|0,668265263);h=Math.imul(h^(h>>>13),1274126177);h^=h>>>16;return (h>>>0)/4294967296}
function vnoise(x,z){const ix=Math.floor(x),iz=Math.floor(z),fx=x-ix,fz=z-iz,sx=fx*fx*(3-2*fx),sz=fz*fz*(3-2*fz);
  const a=hash2(ix,iz),b=hash2(ix+1,iz),c=hash2(ix,iz+1),d=hash2(ix+1,iz+1);return a+(b-a)*sx+(c-a)*sz+(a-b-c+d)*sx*sz}

/* ---------- world constants ---------- */
const HALF=600, EDGE=HALF-5, RES=0.4, N=Math.round(HALF*2/RES)+1;
const HOLE_R=1.25, MR=1.15, CELL=4, OUTER_Y=3.2;
const FIVE_FT=1.5, EIGHT_FT=2.6, FT=5/1.5;
function inCamp(x,z){return z>27&&z<56&&x>-40&&x<30}
function nearCampZone(x,z){return x>-46&&x<36&&z>12&&z<62}
function baseH(x,z){
  let h=(vnoise(x*0.07+11,z*0.07-3)-0.5)*0.6+(vnoise(x*0.31,z*0.31)-0.5)*0.12;
  if(inCamp(x,z))h*=0.25;
  const e=Math.max(Math.abs(x),Math.abs(z));
  if(e>EDGE){const t=Math.min(1,(e-EDGE)/5);h+=t*t*OUTER_Y}
  return h;
}

/* ---------- renderer & scene ---------- */
const renderer=new T.WebGLRenderer({antialias:true,powerPreference:'high-performance'});
/* PERF: phones and tablets (touch-first screens) get cheaper settings: a lower render resolution cap and plain
   (not soft) shadows from a smaller shadow map. Desktops keep the original settings. */
const LOW_POWER=matchMedia('(pointer: coarse)').matches;
const MAX_PR=Math.min(window.devicePixelRatio||1,LOW_POWER?1.25:1.5);
renderer.setPixelRatio(MAX_PR);
renderer.setSize(innerWidth,innerHeight);
renderer.shadowMap.enabled=true;renderer.shadowMap.type=LOW_POWER?T.PCFShadowMap:T.PCFSoftShadowMap;
$('#game').appendChild(renderer.domElement);
const canvas=renderer.domElement;
const scene=new T.Scene();
const FOG_DAY=new T.Color(0xe8d6b4), FOG_RAIN=new T.Color(0x9aa3a8);
scene.fog=new T.Fog(FOG_DAY.getHex(),80,1000);
const camera=new T.PerspectiveCamera(62,innerWidth/innerHeight,0.1,3000);
camera.rotation.order='YXZ';scene.add(camera);
addEventListener('resize',()=>{renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix()});

const hemi=new T.HemisphereLight(0xcfe2ee,0xc28a52,0.62);scene.add(hemi);
const sun=new T.DirectionalLight(0xfff0d2,1.05);sun.castShadow=true;sun.shadow.mapSize.set(LOW_POWER?1024:2048,LOW_POWER?1024:2048);
Object.assign(sun.shadow.camera,{left:-32,right:32,top:32,bottom:-32,near:1,far:170});sun.shadow.camera.updateProjectionMatrix();sun.shadow.bias=-0.0008;
scene.add(sun,sun.target);
const SUN_DIR=new T.Vector3(0.55,0.78,0.3).normalize();

const matCache={};
function M(c,o){const k=c+(o?JSON.stringify(o):'');if(!matCache[k])matCache[k]=new T.MeshStandardMaterial(Object.assign({color:c,flatShading:true,roughness:0.95,metalness:0},o||{}));return matCache[k]}
function box(w,h,d,c){const m=new T.Mesh(new T.BoxGeometry(w,h,d),M(c));m.castShadow=true;m.receiveShadow=true;return m}
function cyl(rt,rb,h,seg,c){const m=new T.Mesh(new T.CylinderGeometry(rt,rb,h,seg),M(c));m.castShadow=true;m.receiveShadow=true;return m}
/* PERF: merge a set of coloured boxes into ONE mesh, so the GPU draws it in one call instead of one per box.
   Each box's colour is baked into a per-vertex colour attribute, which lets every merged mesh share one material.
   parts: [[width, height, depth, colour, x, y, z], ...] (moved up here so the camp buildings below can use it too) */
const mergedMat=new T.MeshStandardMaterial({vertexColors:true,flatShading:true,roughness:0.95,metalness:0});
function mergeBoxes(parts){
  const pos=[],col=[],c=new T.Color();
  for(const[w,h,d,hex,x,y,z]of parts){
    const g=new T.BoxGeometry(w,h,d).toNonIndexed();g.translate(x,y,z);
    const p=g.attributes.position.array;for(let i=0;i<p.length;i++)pos.push(p[i]);
    c.setHex(hex);for(let i=0;i<p.length/3;i++)col.push(c.r,c.g,c.b);g.dispose();
  }
  const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(pos,3));g.setAttribute('color',new T.Float32BufferAttribute(col,3));g.computeVertexNormals();g.computeBoundingSphere();
  return g;
}

/* ---------- sky ---------- */
{
  const g=new T.SphereGeometry(900,32,16);const cols=[];const top=new T.Color(0x78acd3),hor=new T.Color(0xeee0c4),tmp=new T.Color();
  const p=g.attributes.position;for(let i=0;i<p.count;i++){const y=p.getY(i)/900;tmp.copy(hor).lerp(top,clamp(y*1.7,0,1));cols.push(tmp.r,tmp.g,tmp.b)}
  g.setAttribute('color',new T.Float32BufferAttribute(cols,3));
  var sky=new T.Mesh(g,new T.MeshBasicMaterial({vertexColors:true,side:T.BackSide,fog:false,depthWrite:false}));scene.add(sky);
  var sunDisc=new T.Mesh(new T.SphereGeometry(24,16,8),new T.MeshBasicMaterial({color:0xfff7df,fog:false}));
  sunDisc.position.copy(SUN_DIR).multiplyScalar(800);scene.add(sunDisc);
}

